using System.Text.Json;
using Microsoft.AspNetCore.DataProtection;
using Shop.Modules.Cms;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class CmsBlogPostTests
{
    [Fact]public void HttpNullOmissionPolicyMustStillEmitExplicitEmptyArticleMetadata(){var draft=Content()with{AuthorKind=null,BylineFa="",BylineEn=""};var json=JsonSerializer.SerializeToElement(draft,new JsonSerializerOptions(JsonSerializerDefaults.Web){DefaultIgnoreCondition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull});foreach(var key in new[]{"authorKind","cover","coverAltFa","coverAltEn"})Assert.Equal(JsonValueKind.Null,json.GetProperty(key).ValueKind);}
    public static CmsBlogContent Content()=>new(new(new("مقالهٔ ساختگی","شرح نمونه",[new(new string('a',32),"Text","All",Heading:"",Text:"فقط دادهٔ نمونهٔ نرم‌افزار.")]),new("Synthetic article","Sample description",[new(new string('b',32),"Text","All",Heading:"",Text:"Synthetic software sample only.")])),"Organization","تیم نمونه","Sample team",null,null,null,[new("guide","راهنما","Guide")]);
    [Fact]public void PublishRequiresExplicitAuthorAndBothLanguagesWhileEmptyDraftDoesNotGuessAnIdentity(){var x=Content();CmsBlogPostRules.Content(x,true);var draft=x with{AuthorKind=null,BylineFa="",BylineEn=""};CmsBlogPostRules.Content(draft,false);Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Content(draft,true));foreach(var bad in new[]{x with{AuthorKind="Automatic"},x with{AuthorKind=null},x with{BylineFa=""},x with{BylineEn=""},x with{BylineFa="Private\nidentity"},x with{Body=x.Body with{En=x.Body.En with{Title=""}}}})Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Content(bad,true));}
    [Fact]public void CoverNeedsAnApprovedInternalImageAndExplicitAltInBothLanguages(){var x=Content()with{Cover="/products/iphone.svg",CoverAltFa="تصویر نمونه",CoverAltEn="Sample image"};CmsBlogPostRules.Content(x,true);foreach(var bad in new[]{x with{Cover="https://someone.invalid/tracker.png"},x with{CoverAltFa=null},x with{CoverAltEn=""},x with{Cover=null}})Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Content(bad,true));}
    [Fact]public void TagsAreBoundedCanonicalUniqueAndBilingualInsteadOfUnvalidatedFilterJson(){var x=Content();CmsBlogPostRules.Content(x,true);foreach(var tags in new IReadOnlyList<CmsBlogTag>[]{[new("BadSlug","نام","Name")],[new("tag","","Name")],[new("tag","نام","")],[new("b","ب","B"),new("a","ا","A")],[new("a","ا","A"),new("a","ا","A")],Enumerable.Range(1,9).Select(i=>new CmsBlogTag("tag-"+i,"نمونه","Sample")).ToArray()})Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Content(x with{Tags=tags},true));}
    [Fact]public void ArticleReusesApprovedBlocksAndCannotIntroduceRawHtmlOrUnsafeLinks(){var x=Content();foreach(var block in new[]{new CmsPageBlock(new string('a',32),"Html","All",Text:"<script>alert(1)</script>"),new CmsPageBlock(new string('a',32),"Links","All",Links:[new("Unsafe","javascript:alert(1)")]),new CmsPageBlock(new string('a',32),"Text","Unconfigured",Text:"Sample")})Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Content(x with{Body=x.Body with{Fa=x.Body.Fa with{Blocks=[block]}}},true));}
    [Fact]public void PublicationCommandsCannotSilentlyChangeSlugOriginOrOverwriteWithoutVersion(){var x=Content();CmsBlogPostRules.Input(new("Create",Slug:"sample-article",IsDemo:true,Content:x),true);CmsBlogPostRules.Input(new("Publish",Version:"AAAAAAAAAAE=",Confirmed:true),false);foreach(var invalid in new[]{new CmsBlogPostWrite("Publish",Version:"AAAAAAAAAAE="),new("Save",Content:x),new("Publish",Version:"AAAAAAAAAAE=",Slug:"change-address",Confirmed:true),new("Restore",Version:"AAAAAAAAAAE=",RestoreRevisionId:new string('c',32)),new("Save",Version:"AAAAAAAAAAE=",IsDemo:false,Content:x)})Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Input(invalid,false));}
    [Fact]public void RetainedArticleJsonRejectsMissingRequiredMetadataAndUnknownFields(){var x=Content();Assert.Equal(CmsBlogPostRules.Serialize(x),CmsBlogPostRules.Serialize(CmsBlogPostRules.Read<CmsBlogContent>(CmsBlogPostRules.Serialize(x))));var node=System.Text.Json.Nodes.JsonNode.Parse(CmsBlogPostRules.Serialize(x))!.AsObject();node.Remove("authorKind");Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Read<CmsBlogContent>(node.ToJsonString()));node["authorKind"]="Organization";node["privateActor"]="not-public";Assert.Throws<BusinessException>(()=>CmsBlogPostRules.Read<CmsBlogContent>(node.ToJsonString()));}
    [Fact]public void PublicCursorIsBoundToLocaleFilterAndSampleVisibility(){var p=new DataProtectionCmsBlogCursorProtection(new EphemeralDataProtectionProvider());var token=p.Protect("fa","guide",true,"synthetic-only");Assert.Equal("synthetic-only",p.Unprotect("fa","guide",true,token));Assert.Throws<BusinessException>(()=>p.Unprotect("en","guide",true,token));Assert.Throws<BusinessException>(()=>p.Unprotect("fa",null,true,token));Assert.Throws<BusinessException>(()=>p.Unprotect("fa","guide",false,token));Assert.Throws<BusinessException>(()=>p.Unprotect("fa","guide",true,token+"="));}
}
